// Depth and alpha surfaces read by the Z and Alpha blitters. Only the fields used here are known:
// span pointers wrap around at BufferEnd by BufferSize bytes.
class BlitSurfaceBuffer {
public:
    char Unknown[0x1c];
    unsigned short * BufferEnd;     // +0x1c
    int BufferSize;                 // +0x20, bytes

    unsigned short * Wrap(unsigned short * ptr) const
    {
        if (ptr >= BufferEnd) {
            ptr = (unsigned short *)((char *)ptr - BufferSize);
        }
        return ptr;
    }
};
