// Base of all linear span blitters (vtable 0x78952c: ~Blitter, 2 pure slots).
class Blitter {
public:
    virtual ~Blitter() {}
    virtual void BlitForward(void * dest, void const * source, int length, int zmin,
                             unsigned short * zbuf, unsigned short * abuf, int alvl, int warp) const = 0;
    virtual void BlitBackward(void * dest, void const * source, int length, int zmin,
                              unsigned short * zbuf, unsigned short * abuf, int alvl) const = 0;
};

// Base of all run-length encoded span blitters (vtable 0x78953c: ~RLEBlitter, 1 pure slot).
class RLEBlitter {
public:
    virtual ~RLEBlitter() {}
    virtual void Blit(void * dest, void const * source, int length, int leadskip, int zmin,
                      unsigned short * zbuf, unsigned short * abuf, int alvl, int warp,
                      signed char const * zadjust) const = 0;
};

// Order independent blitters run backward spans through BlitForward.
#define BLIT_BACKWARD_FORWARDS \
    virtual void BlitBackward(void * dest, void const * source, int length, int zmin, unsigned short * zbuf, unsigned short * abuf, int alvl) const \
    { \
        BlitForward(dest, source, length, zmin, zbuf, abuf, alvl, 0); \
    }
#define BLIT_FORWARD_DECL virtual void BlitForward(void * dest, void const * source, int length, int zmin, unsigned short * zbuf, unsigned short * abuf, int alvl, int warp) const;
#define BLIT_FORWARD(C) template<class T> void C<T>::BlitForward(void * dest, void const * source, int length, int zmin, unsigned short * zbuf, unsigned short * abuf, int alvl, int warp) const
#define RLE_BLIT_DECL virtual void Blit(void * dest, void const * source, int length, int leadskip, int zmin, unsigned short * zbuf, unsigned short * abuf, int alvl, int warp, signed char const * zadjust) const;
#define RLE_BLIT(C) template<class T> void C<T>::Blit(void * dest, void const * source, int length, int leadskip, int zmin, unsigned short * zbuf, unsigned short * abuf, int alvl, int warp, signed char const * zadjust) const

